<script setup lang="ts">
import {reactive,ref} from 'vue'
import {api,user,refreshAuth,message,notify} from '../api'
import Avatar from './Avatar.vue'
const emit=defineEmits<{saved:[]}>(),busy=ref(false),error=ref(''),uploading=ref(false)
const form=reactive({penName:user.value?.penName||user.value?.username||'',avatarUrl:user.value?.avatarUrl||'',signature:user.value?.signature||'',bio:user.value?.bio||''})
async function image(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;uploading.value=true;error.value='';try{const data=new FormData();data.append('file',file);form.avatarUrl=(await api.post('/member/images',data)).data.url}catch(e){error.value=message(e)}finally{input.value='';uploading.value=false}}
async function save(){busy.value=true;error.value='';try{await api.put('/member/profile',form);await refreshAuth();notify('个人资料已保存');emit('saved')}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
<template><form class="profile-form" @submit.prevent="save"><div class="profile-avatar-row"><Avatar :src="form.avatarUrl" :name="form.penName||user?.username" :size="72"/><div><label class="button secondary small avatar-upload">{{uploading?'上传中…':'选择头像'}}<input type="file" accept="image/jpeg,image/png" :disabled="busy||uploading||user?.permissions.UPLOAD===false" @change="image"/></label><button v-if="form.avatarUrl" type="button" class="text-button" @click="form.avatarUrl=''">恢复默认</button><p class="quiet-note">PNG / JPEG，最大 5 MB</p></div></div><label>笔名<input v-model="form.penName" maxlength="40" :placeholder="user?.username" :disabled="busy"/></label><label>签名<input v-model="form.signature" maxlength="120" placeholder="最多 120 字" :disabled="busy"/></label><label>简介<textarea v-model="form.bio" maxlength="300" rows="3" :disabled="busy"></textarea></label><p v-if="error" class="error-message" role="alert">{{error}}</p><button class="button" :disabled="busy||uploading">{{busy?'保存中…':'保存资料'}}</button></form></template>
